// shot7e.js <file> <outdir> <tag> [W]: the screens the r28 items touch
const { chromium } = require('playwright'); const [file, out, tag, w] = process.argv.slice(2); const W = +(w || 390);
(async () => { const b = await chromium.launch();
  const fresh = async (H) => { const ctx = await b.newContext({ viewport: { width: W, height: H || 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 }); const p = await ctx.newPage(); await p.goto('http://127.0.0.1:8765/' + file); await p.waitForFunction(() => window.__meridian, null, { timeout: 60000 }); await p.evaluate(() => window.__meridian.setScen('base')); await p.waitForTimeout(900); return p; };
  const scrollTo = (p, sel) => p.evaluate(sel => { let e = null; const w = r => { if (e) return; e = r.querySelector(sel); r.querySelectorAll('*').forEach(x => x.shadowRoot && w(x.shadowRoot)); }; w(document); if (!e) return false; const s = [...document.querySelectorAll('.page:not(.under) .scroll')].pop(); s.scrollTop += e.getBoundingClientRect().top - 120; return true; }, sel);
  { const p = await fresh(); await p.evaluate(() => window.__meridian.S().updateItem('water', { cadence: { type: 'day' }, targets: [{ from: 0, cmp: 'at_least', v: 2000, cad: { type: 'day' } }] })); await p.waitForTimeout(200);
    await p.evaluate(() => window.__meridian.S().updateItem('water', { cadence: { type: 'week' }, targets: [{ from: 0, cmp: 'at_least', v: 2000, cad: { type: 'day' } }, { from: window.__meridian.db().today, cmp: 'at_least', v: 2000, cad: { type: 'week' } }] })); await p.waitForTimeout(300);
    await p.evaluate(() => window.__meridian.S().nav.reset('time', [{ k: 'weeks', off: 0 }])); await p.waitForTimeout(1500);
    await scrollTo(p, '.sec .staff'); await p.waitForTimeout(600); await p.screenshot({ path: `${out}/week44-water-day-to-week-${W}-${tag}.png` });
    await p.evaluate(() => { const w = r => { r.querySelectorAll('h2').forEach(h => { if (h.textContent === "This week's aims") { const s = [...document.querySelectorAll('.page:not(.under) .scroll')].pop(); s.scrollTop += h.getBoundingClientRect().top - 120; } }); r.querySelectorAll('*').forEach(x => x.shadowRoot && w(x.shadowRoot)); }; w(document); }); await p.waitForTimeout(600); await p.screenshot({ path: `${out}/week44-aims-${W}-${tag}.png` }); await p.context().close(); }
  { const p = await fresh(); await p.evaluate(() => window.__meridian.S().nav.reset('time', [{ k: 'month', m: 9 }])); await p.waitForTimeout(1500); await scrollTo(p, '.cb[data-id="meditate"]'); await p.waitForTimeout(700); await p.screenshot({ path: `${out}/october-totals-meditation-${W}-${tag}.png` }); await p.context().close(); }
  { const p = await fresh(); await p.evaluate(() => window.__meridian.S().updateItem('guitar', { name: 'Practise the lute', short: 'Practise the lute' })); await p.waitForTimeout(300); await p.evaluate(() => window.__meridian.S().nav.reset('routines', [])); await p.waitForTimeout(1600); await p.screenshot({ path: `${out}/routines-hero-long-name-${W}-${tag}.png` }); await p.context().close(); }
  { const p = await fresh(); await p.evaluate(() => window.__meridian.S().sheet.open({ k: 'target', id: 'no-such-item' })); await p.waitForTimeout(1200); await p.screenshot({ path: `${out}/target-sheet-missing-item-${W}-${tag}.png` }); await p.context().close(); }
  console.log('shots', tag, W); await b.close(); })();
